import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel b8bd735:
# &packet.MovementEffect{EntityRuntimeID: 7, Type: 1, Duration: 40, Tick: 300}
DOLPHIN_BOOST = bytes.fromhex("070250ac02")

# generated by gophertunnel b8bd735:
# &packet.MovementEffect{Type: -1}
INVALID = bytes.fromhex("00010000")

GOLDENS = [
    pytest.param(
        v2168.MovementEffectPacket(
            runtime_id=7, effect_type=v2168.MovementEffectType.DOLPHIN_BOOST, effect_duration=40, tick=300
        ),
        DOLPHIN_BOOST,
        id="v2168-dolphin-boost",
    ),
    pytest.param(
        v2168.MovementEffectPacket(effect_type=v2168.MovementEffectType.INVALID),
        INVALID,
        id="v2168-invalid",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_movement_effect_is_packet_318(version):
    assert version.packets[318] is version.MovementEffectPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_movement_effect_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_movement_effect_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
